def product(model_id="dominar-400"):
 return product_page(D,icon,cta,money,model_id)
def privacy():
 return privacy_body()
def page(body,title,desc,path,ptype='',model_id=''):
 model=next((m for m in D['models'] if m['id']==model_id),None)
 schema={'@context':'https://schema.org','@graph':[{'@type':'MotorcycleDealer','name':'Bajaj InteriorSP — '+u['name'],'url':'https://bajajinteriorsp.com.br/','telephone':'+'+u['phone'],'address':{'@type':'PostalAddress','streetAddress':u['address'],'postalCode':u['cep'],'addressCountry':'BR'},'hasMap':u['maps']} for u in D['units']]}
 if ptype=='product':
  model=model or next(m for m in D['models'] if m['id']=='dominar-400')
  schema['@graph'].append({'@type':'Product','name':'Bajaj '+model['name'],'brand':{'@type':'Brand','name':'Bajaj'},'model':model['year'],'description':desc,'image':'https://bajajinteriorsp.com.br/assets/'+model['image'],'offers':{'@type':'Offer','priceCurrency':'BRL','price':str(model['price'])+'.00','url':'https://bajajinteriorsp.com.br'+path}})
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title}</title><meta name="description" content="{esc(desc)}"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#0052a1"><link rel="canonical" href="https://bajajinteriorsp.com.br{path}"><meta property="og:title" content="{title}"><meta property="og:description" content="{esc(desc)}"><meta property="og:type" content="website"><meta property="og:locale" content="pt_BR"><link rel="icon" href="/assets/favicon.png"><link rel="preload" href="/assets/din-regular.otf" as="font" type="font/otf" crossorigin><link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/blog.css"><link rel="stylesheet" href="/contact-capture.css">{'<link rel="stylesheet" href="/home-hero.css"><link rel="stylesheet" href="/home-commercial.css"><script type="module" src="/home-hero.mjs"></script><script type="module" src="/home-blog.mjs"></script><script type="module" src="/bia-media.mjs"></script><link rel="stylesheet" href="/bia-presentation.css"><link rel="stylesheet" href="/home-units-gallery.css"><script type="module" src="/home-units-gallery.mjs"></script><script type="module" src="/family-film.mjs"></script><script type="module" src="/closing-film.mjs"></script><link rel="stylesheet" href="/home-art-slider.css"><script type="module" src="/home-art-slider.mjs"></script><link rel="stylesheet" href="/home-reveal.css"><script type="module" src="/home-reveal.mjs"></script>' if ptype=='home' else ''}{'<link rel="stylesheet" href="/dominar-400.css"><script type="module" src="/dominar-400.mjs"></script><link rel="stylesheet" href="/product-spin.css"><script type="module" src="/product-spin.mjs"></script>' if ptype=='product' else ''}{'<link rel="stylesheet" href="/service-pages.css"><script type="module" src="/service-request.mjs"></script>' if ptype=='service' else ''}{'<link rel="stylesheet" href="/owner-pages.css"><script type="module" src="/owner-pages.mjs"></script>' if 'owner-page' in body else ''}<script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script><script type="module" src="/app.mjs"></script>{'<link rel="stylesheet" href="/offers.css"><script type="module" src="/offers.mjs"></script>' if path=='/ofertas/' else ''}</head><body data-page="{ptype}" data-model="{model['id'] if model else ''}">{header()}<main id="conteudo">{body}</main>{footer(model)}<noscript><div class="noscript">Sem JavaScript, o site não registra sua solicitação. Ative-o para enviar o formulário ou fale diretamente com vendas: <a href="https://wa.me/5517992606039">Rio Preto</a> ou <a href="https://wa.me/5514996448094">Bauru</a>.</div></noscript></body></html>'''
pages=[('/',home(),'Bajaj InteriorSP | Motos em Rio Preto e Bauru','Conheça a linha Bajaj, consulte preços e fale com a BIA de São José do Rio Preto ou Bauru. Solicite simulação e test ride.','home',''),('/privacidade/',privacy(),'Privacidade e preferências | Bajaj InteriorSP','Saiba como funciona a escolha de unidade e o contato pelo WhatsApp nesta prévia da Bajaj InteriorSP.','privacy','')]
for m in D['models']:
 desc='Dominar 400 2026/2027: 373,27 cc, 40 CV e quatro modos de pilotagem. Conheça os detalhes e fale com a BIA em Rio Preto ou Bauru.' if m['id']=='dominar-400' else f"{m['name']} {m['year']}: conheça preço, fotos e ficha técnica. Solicite simulação ou test ride com a BIA em Rio Preto ou Bauru."
 pages.append((f"/motos/{m['id']}/",product(m['id']),f"{m['name']} | {money(m['price'])} | Bajaj InteriorSP",desc,'product',m['id']))
for kind in ['ofertas','financiamento','test-ride','pos-venda','unidades','a-interiorsp','consorcio','garantia','manuais','revisoes']:
 body,title,desc=support_page(kind,D,icon,cta,money,finance,units)
 path=f'/pos-venda/{kind}/' if kind in ['garantia','manuais','revisoes'] else f'/{kind}/'
 pages.append((path,body,title+' em Rio Preto e Bauru | Bajaj InteriorSP',desc,'service',''))
for path,body,title,desc,typ,model_id in pages:
 if path=='/ofertas/':
  (out/'ofertas'/'index.html').unlink(missing_ok=True)
  continue
 dest=out/path.strip('/');dest.mkdir(parents=True,exist_ok=True);(dest/'index.html').write_text(page(body,title,desc,path,typ,model_id))
shutil.copy(P/'data.json',out/'data.json')
(out/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
(out/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://bajajinteriorsp.com.br'+p[0]+'</loc></url>' for p in pages if p[0]!='/privacidade/')+'</urlset>')
print(f'Geradas {len(pages)-1} páginas estáticas e fragmentos comerciais dinâmicos. Dados centralizados; preços preservados do briefing.')

# Shared chrome and approved catalog for the dynamic Blog.
(P/'lib'/'site-fragments.mjs').write_text('export const siteHeader='+json.dumps(header(),ensure_ascii=False)+';\nexport const siteFooter='+json.dumps(footer(),ensure_ascii=False)+';\nexport const contactDialogHTML='+json.dumps(contact_dialog(D,icon),ensure_ascii=False)+';\n'+ 'export const siteOffersHero='+json.dumps(__import__('re').search(r'<section class="service-hero">.*?</section>', next(item[1] for item in pages if item[0]=='/ofertas/')).group(0),ensure_ascii=False)+';\n'+ 'export const siteOffersCatalog='+json.dumps(offers_body(D,icon,money),ensure_ascii=False)+';\n')
_blog_assets=json.loads((P/'model-assets.json').read_text())
_blog_covers=[{'file':'campaign-client-01.webp','label':'Linha Bajaj — arte aprovada'}]
for _key,_label in [('refresh-dominar-ns400z-intro','Dominar NS400Z — foto oficial'),('d250-1','Dominar 250 — foto oficial'),('refresh-pulsar-n150-intro','Pulsar N150 — foto oficial')]:
 _blog_covers.append({'file':_blog_assets[_key]['large']['file'],'label':_label})
_blog_models=[{_k:_m.get(_k) for _k in ['id','name','price','year','image','catalogImage']} for _m in D['models']]
(P/'lib'/'blog-catalog.mjs').write_text('export const models='+json.dumps(_blog_models,ensure_ascii=False)+';\nexport const units='+json.dumps(D['units'],ensure_ascii=False)+';\nexport const coverAssets='+json.dumps(_blog_covers,ensure_ascii=False)+';\nexport const initialArticles='+json.dumps(json.loads((P/'blog-seed.json').read_text()),ensure_ascii=False)+';\n')

shutil.copyfile(P/"lib"/"blog-card.mjs",out/"blog-card.mjs")

